examples.template:
VStack(alignment: .leading, spacing: 12) {
    MonarchApprovalChainEditor(
        steps: $steps,
        approverTypes: [
            MonarchApprovalApproverType(id: {{approverTypes.0.value}}, label: {{approverTypes.0.label}}),
            MonarchApprovalApproverType(id: {{approverTypes.1.value}}, label: {{approverTypes.1.label}}),
            MonarchApprovalApproverType(id: {{approverTypes.2.value}}, label: {{approverTypes.2.label}}),
            MonarchApprovalApproverType(
                id: {{approverTypes.3.value}},
                label: {{approverTypes.3.label}},
                targets: [
                    MonarchComboboxOption(id: {{approverTypes.3.targets.0.value}}, label: {{approverTypes.3.targets.0.label}}),
                    MonarchComboboxOption(id: {{approverTypes.3.targets.1.value}}, label: {{approverTypes.3.targets.1.label}}),
                ],
                targetLabel: {{approverTypes.3.targetLabel}}
            ),
            MonarchApprovalApproverType(
                id: {{approverTypes.4.value}},
                label: {{approverTypes.4.label}},
                targets: [
                    MonarchComboboxOption(id: {{approverTypes.4.targets.0.value}}, label: {{approverTypes.4.targets.0.label}}),
                    MonarchComboboxOption(id: {{approverTypes.4.targets.1.value}}, label: {{approverTypes.4.targets.1.label}}),
                ],
                targetLabel: {{approverTypes.4.targetLabel}}
            ),
        ],
        description: {{description}},
        showsErrors: tried
    )
    MonarchButton({{saveLabel}}, variant: .primary) {
        tried = true
    }
}

examples.setupTemplate:
@State private var steps = [
    MonarchApprovalChainStep(id: {{steps.0.id}}, approver: {{steps.0.approver}}),
    MonarchApprovalChainStep(id: {{steps.1.id}}, approver: {{steps.1.approver}}, label: {{steps.1.label}}),
]
@State private var tried = false

examples.setup:
@State private var steps = [
    MonarchApprovalChainStep(id: "1", approver: "manager"),
    MonarchApprovalChainStep(id: "2", approver: "role", label: "Finance check"),
]
@State private var tried = false

examples.code:
VStack(alignment: .leading, spacing: 12) {
    MonarchApprovalChainEditor(
        steps: $steps,
        approverTypes: [
            MonarchApprovalApproverType(id: "manager", label: "Reporting manager"),
            MonarchApprovalApproverType(id: "manager-2", label: "Manager’s manager"),
            MonarchApprovalApproverType(id: "head", label: "Department head"),
            MonarchApprovalApproverType(
                id: "role",
                label: "Anyone with a role",
                targets: [
                    MonarchComboboxOption(id: "finance", label: "Finance team"),
                    MonarchComboboxOption(id: "people", label: "People team"),
                ],
                targetLabel: "Role"
            ),
            MonarchApprovalApproverType(
                id: "person",
                label: "A named person",
                targets: [
                    MonarchComboboxOption(id: "p1", label: "Jo Park"),
                    MonarchComboboxOption(id: "p2", label: "Ana Ruiz"),
                ],
                targetLabel: "Person"
            ),
        ],
        description: "Each step is decided by one of the people it names. A step whose approver is the requester is skipped.",
        showsErrors: tried
    )
    MonarchButton("Save chain", variant: .primary) {
        tried = true
    }
}
